// OAuthTokens represents the complete token response
type OAuthTokens struct {
	TokenType    string                 `json:"token_type"`
	AccessToken  string                 `json:"access_token"`
	ExpiresIn    int                    `json:"expires_in"`
	RefreshToken string                 `json:"refresh_token"`
	Scope        string                 `json:"scope"`
	Organization map[string]interface{} `json:"organization"`
	Account      map[string]interface{} `json:"account"`
	ExpiresAt    int64                  `json:"expires_at"`
	CreatedAt    string                 `json:"created_at"`
}

const (
	clientID     = "9d1c250a-e61b-44d9-88ed-5944d1962f5e"
	authorizeURL = "https://claude.ai/oauth/authorize"
	tokenURL     = "https://console.anthropic.com/v1/oauth/token"
	redirectURI  = "https://console.anthropic.com/oauth/code/callback"
	scope        = "org:create_api_key user:profile user:inference"
)

func main() {
	fmt.Println("=== Claude Max OAuth - Working Implementation ===")
	fmt.Println("Based on anthropic-oauth-max-plan CLI")
	fmt.Println()

	// Generate PKCE parameters
	verifier := generateCodeVerifier()
	challenge := generateCodeChallenge(verifier)
	state := generateState()

	// Build authorization URL
	authURL := buildAuthURL(challenge, state)

	fmt.Println("🔐 Starting OAuth flow...")
	fmt.Println()
	fmt.Println("Opening browser to:")
	fmt.Println(authURL)
	fmt.Println()

	openBrowser(authURL)

	fmt.Println("=" + strings.Repeat("=", 69))
	fmt.Println("After authorizing, the page will show a code and state.")
	fmt.Println("Copy them and paste in this format: code#state")
	fmt.Println("Example: abc123xyz...#def456uvw...")
	fmt.Println("=" + strings.Repeat("=", 69))
	fmt.Println()

	reader := bufio.NewReader(os.Stdin)
	fmt.Print("Paste code#state here: ")
	input, _ := reader.ReadString('\n')
	codeState := strings.TrimSpace(input)

	if !strings.Contains(codeState, "#") {
		fmt.Println("❌ Invalid format. Expected: code#state")
		return
	}

	parts := strings.Split(codeState, "#")
	code := parts[0]
	returnedState := parts[1]

	// Validate state (CSRF protection)
	if returnedState != state {
		fmt.Println("❌ State mismatch - possible CSRF attack")
		fmt.Printf("Expected: %s\n", state)
		fmt.Printf("Got:      %s\n", returnedState)
		return
	}

	fmt.Println("\n✅ Authorization code received!")
	fmt.Println("\n🔄 Exchanging for tokens...")

	// Exchange code for tokens
	tokens, err := exchangeCodeForTokens(code, verifier, returnedState)
	if err != nil {
		fmt.Printf("❌ Token exchange failed: %v\n", err)
		return
	}

	fmt.Println("✅ Tokens obtained successfully!")
	fmt.Println()
	fmt.Printf("Access Token:  %s...\n", tokens.AccessToken[:40])
	fmt.Printf("Refresh Token: %s...\n", tokens.RefreshToken[:40])
	fmt.Printf("Scope:         %s\n", tokens.Scope)
	fmt.Printf("Expires In:    %d seconds (%d hours)\n", tokens.ExpiresIn, tokens.ExpiresIn/3600)
	fmt.Println()

	// Test the token immediately
	fmt.Println("🧪 Testing token with API call...")
	if err := testToken(tokens.AccessToken); err != nil {
		fmt.Printf("❌ API test failed: %v\n", err)
		return
	}

	fmt.Println("\n🎉 SUCCESS! OAuth authentication working!")
	fmt.Println()
	fmt.Println("✅ Token exchange successful")
	fmt.Println("✅ API authentication successful")
	fmt.Println("✅ Claude Max OAuth tokens work with Anthropic API!")
}

func buildAuthURL(challenge, state string) string {
	params := url.Values{
		"code":                  {"true"},
		"client_id":             {clientID},
		"redirect_uri":          {redirectURI},
		"response_type":         {"code"},
		"scope":                 {scope},
		"code_challenge":        {challenge},
		"code_challenge_method": {"S256"},
		"state":                 {state},
	}
	return authorizeURL + "?" + params.Encode()
}

func exchangeCodeForTokens(code, codeVerifier, state string) (*OAuthTokens, error) {
	requestBody := map[string]string{
		"code":          code,
		"state":         state,
		"grant_type":    "authorization_code",
		"client_id":     clientID,
		"redirect_uri":  redirectURI,
		"code_verifier": codeVerifier,
	}

	jsonData, _ := json.Marshal(requestBody)

	resp, err := http.Post(tokenURL, "application/json", bytes.NewBuffer(jsonData))
	if err != nil {
		return nil, fmt.Errorf("request failed: %w", err)
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(resp.Body)

	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, string(body))
	}

	var tokens OAuthTokens
	if err := json.Unmarshal(body, &tokens); err != nil {
		return nil, fmt.Errorf("parse failed: %w", err)
	}

	// Add timestamps (for compatibility with CLI format)
	tokens.ExpiresAt = int64(tokens.ExpiresIn) * 1000
	tokens.CreatedAt = "now"

	return &tokens, nil
}

